toad_implementation.code_blueprint:
canvas {
  size: 900px 650px;
  fill: #000000;
  font-family: "Courier Prime, monospace";
}

>black = #000000;
>white = #FFFFFF;
>dim = #777777;

rect #negativeBorder {
  at: center of canvas;
  size: 820px 520px;
  fill: #0D0D0D;
  stroke: #222222;
  stroke-width: 2px;
}

rect #photoWindow {
  at: center of #negativeBorder;
  size: 720px 420px;
  fill: #1A1A1A;
  stroke: >white;
  stroke-width: 1px;
}

text #frameMetaTop {
  at: top left of #negativeBorder offset 24px 12px;
  content: "KODAK TRI-X 400  ••  EXP 24A  ••  ISO 400";
  font-size: 11px;
  color: >dim;
}

text #sceneHeadline {
  at: bottom left of #photoWindow offset 24px -24px;
  content: "PARIS, RUE DE BELLEVILLE  //  14:32";
  font-size: 14px;
  font-weight: 700;
  color: >white;
}

text #creditsBottom {
  at: bottom right of #negativeBorder offset -24px -12px;
  content: "CHLOÉ BEAUCHAMP PHOTOGRAPHY";
  font-size: 10px;
  color: >dim;
}
